def literal_signature(data):
    return [(x['id'],x['group'],x['requirement']) for x in data['requirements']]


def generate():
    data=json.loads((ROOT/'contract_requirements.json').read_text(encoding='utf-8'))
    frozen=json.loads((BASE/'contract_requirements.json').read_text(encoding='utf-8'))
    if len(data['requirements'])!=41 or literal_signature(data)!=literal_signature(frozen):
        raise ValueError('The 41 IDs, groups, order and literal requirements must match the frozen source.')
    if set(mapping)!={x['id'] for x in data['requirements']}:
        raise ValueError('Every requirement must have exactly one mapping.')
    if not (ROOT/'supplement/08_archive.md').is_file():
        raise FileNotFoundError('The historical archive appendix must exist before regeneration.')
    current=dict(mapping)
    if REVIEW_WORD.is_file():
        word_link=f'[Word для рецензирования]({REVIEW_WORD.relative_to(ROOT).as_posix()})'
        current['Р10']=(f'Исходники настоящего отчёта; {word_link}',
            'Редактируемый Word для рецензирования сформирован. Включение последних редакционных правок, окончательный объём и вёрстка проверяются при финальной сборке; готовность полного архива этим не подтверждается.')
        current['С05']=(f'{word_link}; редакционные исходники; {ARCHIVE}',
            'Word для рецензирования подготовлен; актуальность финальной сборки проверяется отдельно. Исследовательский архив в эту редакцию не передавался, презентация не включена. Подготовка документа не подтверждает комплектность или факт передачи полного набора результатов.')
    for item in data['requirements']:
        item['evidence'],item['status']=current[item['id']]
    head='''# Приложение А Матрица соответствия договору

Матрица содержит все 41 переданное требование. Коды введены для навигации, текст требований отделён от пояснений автора. Наличие описания работы не означает доказанности положительной характеристики методики. «Частично подтверждено» ограничивает охват проверки; «не подтверждено» относится к конкретному требованию; «отдельная поставка» обозначает файлы, комплектность которых не удостоверяется данным отчётом.

Историческая опись, ограничения целостности и доступные программные точки входа приведены в [приложении И](supplement/08_archive.md). Исследовательский архив в эту редакцию не передавался. Готовность Word для рецензирования отделяется от актуальности окончательной сборки и передачи полного комплекта.

'''
    parts=[head]
    groups=list(dict.fromkeys(x['group'] for x in data['requirements']))
    for i,group in enumerate(groups,1):
        parts += [f'## {group}\n\n<details>\n<summary>Таблица А.{i} — {group}</summary>\n\n',
                  '| Код | Требование договора | Раздел | Статус и ограничение |\n|---|---|---|---|\n']
        parts += [f"| {x['id']} | {x['requirement']} | {x['evidence']} | {x['status']} |\n" for x in data['requirements'] if x['group']==group]
        parts += ['\n</details>\n\n']
    text=''.join(parts)
    return {'contract_requirements.json':json.dumps(data,ensure_ascii=False,indent=2)+'\n',
            'contract_matrix.md':text,'appendices.md':text}


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true',help='Verify generated contents without writing files.')
    args=parser.parse_args()
    outputs=generate()
    if args.check:
        stale=[name for name,text in outputs.items() if (ROOT/name).read_text(encoding='utf-8')!=text]
        if stale:
            raise SystemExit('Regeneration required: '+', '.join(stale))
        print('Checked all 41 literal requirements and all three generated files; no writes.')
    else:
        for name,text in outputs.items():
            (ROOT/name).write_text(text,encoding='utf-8')
        print('Regenerated matrix/appendices/JSON; all 41 frozen literal requirements unchanged.')


if __name__=='__main__':
    main()
